"""Copy the plugin's shaders and constants into the demo, by script, never by hand.

    python3 demo/tools/sync_shaders.py          rewrite the generated block of demo/plugin.js
    python3 demo/tools/sync_shaders.py --print  print the block instead

`demo/plugin.js` carries one region between the lines

    //=== BEGIN GENERATED by demo/tools/sync_shaders.py
    //=== END GENERATED

and this script owns it. Everything in it is text lifted out of the C++:

  - the five GLSL strings of `source/Shaders.cpp` (the version line, the vertex
    body and the capture, resample and output bodies), each spliced into a
    JavaScript template literal with its tabs, its comments and its blank lines
    exactly as they are. A template literal cannot hold a raw backtick, a
    backslash or a `${`, so those three are escaped (none occurs today) and
    `check_shaders.py` undoes exactly those three and refuses any other escape;
  - the print-data layout (`source/Shaders.h`);
  - every constant of `source/Model.h` -- the film's geometry, the two hands'
    partials and deviations, the shutter's segment cap, the weave law, the
    scratch, dust and hair rates and sizes, the curve, the grain, the fog, the
    reel's slip and tails, the tones -- and its enums (Side, Tail, Tone,
    Perturb, Probe), plus `Model.cpp`'s hash-stream enum;
  - each stock's seven Smits weights (`source/Spectral.h`, itself generated by
    `tools/spectral_weights.py`);
  - the control counts and option lists (`source/Controls.h`, `Controls.cpp`);
  - `Handleman.cpp`'s own constants (the clock's votes, the deepest ring, the
    plugin's hash streams) and `Handleman.h`'s print seed.

Each literal is copied as the C++ spells it; an expression naming another
constant (kMargin, kPitch, kApertureHeightMm, the partials' 1 / kFramesPerTurn)
is copied with that name pointed at the copied constant, so JavaScript
evaluates it in double as the compiler does; a `float` constant, and every
Spectral.h weight, is wrapped in Math.fround, because the plugin promotes the
float, not the decimal, when it computes with it.

What this script does NOT write is the port: the hash, the two hands, the
shutter's closed form, the segments, the weave, the scratches, dust and hair,
the fog and the reel, the tones' laws, every control's law and
Handleman::ProcessOpenGL's clock, cranks, pull-downs, camera, ring and frame
table in plugin.js are a hand translation of Model.cpp, Controls.cpp,
FilmRing.cpp and Handleman.cpp, and only a reader checks those (or
demo/tools/crosscheck, which renders both and compares the pixels).

Run it whenever a shader or a constant changes in the plugin, then
`python3 demo/tools/check_shaders.py` (tools/verify.sh runs it) to confirm.
"""
import os
import re
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
REPO = os.path.abspath(os.path.join(HERE, "..", ".."))
PLUGIN_JS = os.path.join(REPO, "demo", "plugin.js")

BEGIN = "//=== BEGIN GENERATED by demo/tools/sync_shaders.py"
END = "//=== END GENERATED"

# JS constant, C++ symbol in source/Shaders.cpp. Order is the file's order.
SHADERS = [
    ("VERTEX_BODY", "kVertexBody"),
    ("CAPTURE_BODY", "kCaptureBody"),
    ("RESAMPLE_BODY", "kResampleBody"),
    ("OUTPUT_BODY", "kOutputBody"),
]

# Model.h's enums, in the file's order.
MODEL_ENUMS = ["Side", "Tail", "Tone", "Perturb", "Probe"]


def read(path):
    with open(os.path.join(REPO, path)) as handle:
        return handle.read()


def cpp_shader(source, symbol):
    match = re.search(r'const char\* const ' + symbol + r' = R"\((.*?)\)";', source, re.S)
    if match is None:
        raise SystemExit(f"{symbol} not found in source/Shaders.cpp")
    return match.group(1)


def cpp_version(source):
    match = re.search(r'const char\* const kVersion = "(.*?)";', source)
    if match is None:
        raise SystemExit("kVersion not found in source/Shaders.cpp")
    return match.group(1)


def escape_template(text):
    return text.replace("\\", "\\\\").replace("`", "\\`").replace("${", "\\${")


def number(token):
    """A C++ numeric literal as JavaScript: drop a float's f suffix and a u suffix, nothing else."""
    token = token.strip()
    token = re.sub(r"(?<=[0-9.])f\b", "", token)
    token = re.sub(r"(?<=[0-9a-fA-F])u\b", "", token)
    return token


def expression(expr, prefix):
    """A C++ constant expression as JavaScript, every kName pointed at `prefix`."""
    expr = re.sub(r"\s+", " ", number(expr))
    return re.sub(r"\b(k\w+)\b", prefix + r".\1", expr)


def scalars(source, types, prefix):
    """`constexpr T kName = expr;` -> (name, JavaScript expression), in file order."""
    out = []
    for match in re.finditer(r"constexpr (" + types + r") (k\w+)\s*=\s*([^;{\[]+);", source):
        kind, name, expr = match.group(1), match.group(2), match.group(3)
        expr = expression(expr, prefix)
        if kind == "float":
            expr = f"Math.fround({expr})"
        out.append((name, expr))
    return out


def double_arrays(source, prefix):
    """`constexpr double kName[ N ] = { a, b, c };` -> (name, JavaScript array)."""
    out = []
    for match in re.finditer(r"constexpr double (k\w+)\[ [^\]]+ \]\s*=\s*\{([^}]*)\};", source):
        items = [expression(t, prefix) for t in match.group(2).split(",") if t.strip()]
        out.append((match.group(1), "[" + ", ".join(items) + "]"))
    return out


def partial_arrays(source, prefix):
    """`constexpr Partial kName[ N ] = { { f, share }, ... };` -> (name, JavaScript array of objects)."""
    out = []
    for match in re.finditer(r"constexpr Partial (k\w+)\[ [^\]]+ \]\s*=\s*\{(.*?)\};", source, re.S):
        rows = re.findall(r"\{([^{}]*)\}", match.group(2))
        items = []
        for row in rows:
            freq, share = [expression(t, prefix) for t in row.split(",")]
            items.append(f"{{ cyclesPerFrame: {freq}, share: {share} }}")
        out.append((match.group(1), "[" + ", ".join(items) + "]"))
    return out


def enum_values(source, name):
    """`enum Name : T { kA = v, kB, ... };` -> [(kA, JavaScript value), ...], C++'s counting."""
    match = re.search(r"enum " + name + r" : \w+\s*\{(.*?)\};", source, re.S)
    if match is None:
        raise SystemExit(f"enum {name} not found")
    body = re.sub(r"//[^\n]*", "", match.group(1))
    out = []
    previous = -1
    for entry in [e.strip() for e in body.split(",") if e.strip()]:
        if "=" in entry:
            key, value = [p.strip() for p in entry.split("=", 1)]
            value = number(value)
            # Only integer literals and shifts occur; refuse anything else
            # rather than evaluate it.
            if not re.fullmatch(r"[0-9xXa-fA-F <]+", value):
                raise SystemExit(f"enum {name}: {key} = {value} is not a literal or a shift")
            current = eval(value, {"__builtins__": {}}, {})  # noqa: S307 -- checked above
        else:
            key = entry
            current = previous + 1
        out.append((key, str(current)))
        previous = current
    return out


def names_of(controls_cpp, function):
    match = re.search(function + r"\( int index \)\s*\{\s*static const char\* const names\[ \w+ \] = \{ (.*?) \};", controls_cpp, re.S)
    if match is None:
        raise SystemExit(f"{function}'s names not found in source/Controls.cpp")
    return re.findall(r'"([^"]*)"', match.group(1))


def spectral_weights(spectral_h):
    """Spectral.h's kWeights: [(stock, [seven weights as Math.fround]), ...]."""
    match = re.search(r"constexpr Weights kWeights\[ \w+ \] = \{(.*?)\n\};", spectral_h, re.S)
    if match is None:
        raise SystemExit("kWeights not found in source/Spectral.h")
    out = []
    for stock, values in re.findall(r'\{ "([^"]*)", \{ ([^}]*) \} \}', match.group(1)):
        out.append((stock, [f"Math.fround({number(v)})" for v in values.split(",")]))
    return out


def plugin_constants(handleman_cpp, handleman_h):
    """Handleman.cpp's anonymous-namespace constants and Handleman.h's print seed."""
    out = scalars(handleman_cpp, "int|uint32_t", "HANDLEMAN_CPP")
    match = re.search(r"uint32_t seed\s*=\s*(0x[0-9a-fA-F]+u?);", handleman_h)
    if match is None:
        raise SystemExit("the print seed not found in source/Handleman.h")
    out.append(("seed", number(match.group(1))))
    return out


def assignments(name, pairs):
    lines = [f"const {name} = {{}};"]
    for key, expr in pairs:
        lines.append(f"{name}.{key} = {expr};")
    return lines


def block():
    shaders_cpp = read("source/Shaders.cpp")
    shaders_h = read("source/Shaders.h")
    model_h = read("source/Model.h")
    model_cpp = read("source/Model.cpp")
    spectral_h = read("source/Spectral.h")
    controls_h = read("source/Controls.h")
    controls_cpp = read("source/Controls.cpp")
    handleman_cpp = read("source/Handleman.cpp")
    handleman_h = read("source/Handleman.h")

    out = [BEGIN + " from source/ -- do not edit by hand.", ""]
    out.append("// source/Shaders.cpp, verbatim. `assemble` (below the block) is Shaders.cpp's.")
    out.append(f'const K_VERSION = "{cpp_version(shaders_cpp)}";')
    out.append("")
    for name, symbol in SHADERS:
        out.append(f"const {name} = `{escape_template(cpp_shader(shaders_cpp, symbol))}`;")
        out.append("")

    out.append("// source/Shaders.h: the print data's layout, one row of RGBA32F texels.")
    out.extend(assignments("SHADERS_H", scalars(shaders_h, "int", "SHADERS_H")))
    out.append("")

    out.append("// source/Model.h: the film, the hands, the shutter, the weave, the print, the reel, the tones.")
    model = scalars(model_h, "double|float|int", "MODEL_H")
    model += partial_arrays(model_h, "MODEL_H")
    model += double_arrays(model_h, "MODEL_H")
    for enum in MODEL_ENUMS:
        model += enum_values(model_h, enum)
    out.extend(assignments("MODEL_H", model))
    out.append("")

    out.append("// source/Model.cpp: one hash stream per thing the film draws.")
    out.extend(assignments("MODEL_CPP", enum_values(model_cpp, "Stream")))
    out.append("")

    out.append("// source/Spectral.h (generated by tools/spectral_weights.py): each stock's Smits weights,")
    out.append("// white, cyan, magenta, yellow, red, green, blue.")
    out.extend(assignments("SPECTRAL_H", scalars(spectral_h, "int", "SPECTRAL_H")))
    out.append("const SPECTRAL_WEIGHTS = [")
    for stock, weights in spectral_weights(spectral_h):
        out.append(f"  ['{stock}', [{', '.join(weights)}]],")
    out.append("];")
    out.append("")

    out.append("// source/Controls.h and Controls.cpp: the option counts and lists.")
    out.extend(assignments("CONTROLS_H", scalars(controls_h, "int", "CONTROLS_H")))
    for js, fn in (("BLADES_NAMES", "BladesName"), ("STOCK_NAMES", "StockName"), ("TONE_NAMES", "ToneName"), ("TAIL_NAMES", "TailName")):
        out.append(f"const {js} = [" + ", ".join(f"'{n}'" for n in names_of(controls_cpp, fn)) + "];")
    out.append("")

    out.append("// source/Handleman.cpp's constants and source/Handleman.h's print seed.")
    out.extend(assignments("HANDLEMAN_CPP", plugin_constants(handleman_cpp, handleman_h)))
    out.append("")
    out.append(END)
    return "\n".join(out)


def region(js):
    start = js.find(BEGIN)
    stop = js.find(END)
    if start < 0 or stop < 0 or stop < start:
        return None
    return start, stop + len(END)


def main():
    text = block()
    if "--print" in sys.argv:
        print(text)
        return 0
    with open(PLUGIN_JS) as handle:
        js = handle.read()
    where = region(js)
    if where is None:
        raise SystemExit("demo/plugin.js has no generated block (the BEGIN/END GENERATED lines)")
    updated = js[: where[0]] + text + js[where[1]:]
    if updated == js:
        print("demo/plugin.js already matches the plugin's sources")
        return 0
    with open(PLUGIN_JS, "w") as handle:
        handle.write(updated)
    print("demo/plugin.js: generated block rewritten from source/")
    return 0


if __name__ == "__main__":
    sys.exit(main())
